+    amr_hdr = (uint8_t *)g_malloc(AMR_NB_OA_HDR_LEN + amr_payload_len);
+    amr_hdr[0] = 0xf0; /* CMR = 15 = "no change" */
+    amr_hdr[1] = (0 << 7) | /* F=0 */
+                 ((amr_ft & 0x0f) << 3) |
+                 (amr_q && 0x01) << 2;
+    memcpy(amr_hdr + AMR_NB_OA_HDR_LEN, amr_payload, amr_payload_len);
+    return amr_hdr;
+}
